edits.anchor:
// v13.15, from his telemetry: three runs, two knock-downs each, medical
// carried every time and applied zero times. The belt cell for it is built
// automatically and the freebie kit issues two Bandages, so nothing was
// stopping him; nothing had ever said so either. Only when it is true.
if(T.diedWithMed)
  s.textContent+='   \u00b7   YOU DIED CARRYING MEDICAL YOU NEVER USED';

edits.replacement:
// v24.xx, HIS QUESTION (2026-10-12) about this card: "you died carrying medical you never used, soooo random, why is that
// where it is". It was a v13.15 hint from his early telemetry (medical carried on every run, applied on none), bolted onto the
// end of the KILLED BY line, so it read as a random nag in the middle of the facts of the death. A death card says what killed
// you, with what and where, and does not lecture. The line is gone; the flag is still recorded at the moment of death for the
// run report (unusedMed), which is where it came from.

check:
{v:'VER',what:'his question: the KIA card no longer tacks YOU DIED CARRYING MEDICAL YOU NEVER USED onto the killed by line, and the run report still records it',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__loop&&window.__keysRef&&window.__endRaid))
     return 'SKIP: this fixture cannot drive a live raid';
   var bad=[], T0=performance.now();
   var NEEDLE='NEVER'+' USED', NEEDLE2='CARRYING'+' MEDICAL';
   function frames(k){ for(var f=0;f<(k||6);f++){ T0+=16.7; var st=__state(); if(!st) return; __loop(T0); } }
   function keysOff(){ var K=__keysRef(); for(var kk in K) K[kk]=false; }
   function killHim(bagItems){
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state();
     if(!g||!g.player||!g.frags||!g.bag) return null;
     keysOff();
     g.bag.length=0;
     for(var b=0;b<bagItems.length;b++) g.bag.push(bagItems[b]);
     var p=g.player;
     p.hp=12; p.iv=0; p.downed=false; p.pendKiller=null; p.revived=true;
     g.frags.push({x:p.x,y:p.y,t:0,fuse:0.05,mine:1});
     frames(20);
     var s1=__state();
     if(!s1||!s1.player||!s1.player.downed) return null;
     s1.player.downT=0.01;
     for(var _dw=0;_dw<40;_dw++){ var _st=__state(); if(_st&&_st.over) break; frames(10); }
     return __state();
   }
   try{
     var a=killHim(['bandage','bandage']);
     if(!a) return 'SKIP: the charge did not finish him, so there is no card to read';
     if(!a.over) return 'SKIP: the raid did not end, so there is no card to read';
     if(!a.tel||!a.tel.diedWithMed)
       bad.push('dying with unused medical is no longer recorded for the run report (only the card line was meant to go)');
     frames(6);
     var el=document.getElementById('outcome');
     var txt=el?String(el.textContent||''):'';
     if(!el||txt.indexOf('KILLED BY')<0) return 'SKIP: no KIA card on screen to read';
     if(txt.indexOf(NEEDLE)>=0||txt.indexOf(NEEDLE2)>=0)
       bad.push('the KIA card still tacks the unused medical line onto the killed by line');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{
     try{ keysOff(); }catch(_k){}
     try{ var g6=__state(); if(g6&&!g6.over){ g6.player.downed=false; __endRaid('abandon'); } }catch(_e){}
     try{ G=null; keys={}; showScreen('hub'); }catch(_q){}
     try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
   }
   return bad.length?bad.join('; '):null; }},
